subroutine scan_affine_decay_fp64(y, c, x, LEN_1D) bind(C, name="scan_affine_decay_fp64"); use iso_c_binding; implicit none; integer(c_int64_t), value, intent(in) :: LEN_1D; real(c_double), intent(out) :: y(LEN_1D); real(c_double), intent(in) :: c(LEN_1D); real(c_double), intent(in) :: x(LEN_1D); integer(c_int64_t) :: i; real(c_double) :: cur; if (LEN_1D <= 0_c_int64_t) return; cur = x(1); y(1) = cur; do i = 2, LEN_1D; cur = c(i) * cur + x(i); y(i) = cur; end do; end subroutine scan_affine_decay_fp64